WHENEVER SQLERROR EXIT FAILURE ROLLBACK
SET DEFINE OFF
SET SQLBLANKLINES ON
-- Current-production technical report attachment; no source actors or business data.
DECLARE n NUMBER; matched NUMBER;
BEGIN
 IF USER IN ('SYS','SYSTEM') OR SYS_CONTEXT('USERENV','SESSION_USER')<>SYS_CONTEXT('USERENV','CURRENT_SCHEMA') THEN RAISE_APPLICATION_ERROR(-20230,'Connect as isolated application owner'); END IF;
 SELECT COUNT(*) INTO n FROM T_CORE_REPORT_CONFIG_LINE WHERE ID=1694089578136256 AND REPORTCONFIGID='homePageReport' AND REPORTCONFIGLINENO='tjrwrkyzypltj' AND REPORTCATEGORY='fanruan';
 IF n<>1 THEN RAISE_APPLICATION_ERROR(-20231,'Expected report configuration is absent'); END IF;
 SELECT COUNT(*) INTO n FROM T_CORE_FILE WHERE ID=1870065166382528 OR TARGETID='T_CORE_REPORT_CONFIG_LINE$1694089578136256';
 IF n<>0 THEN
  SELECT COUNT(*) INTO matched FROM T_CORE_FILE WHERE ID='1870065166382528' AND TARGETID='T_CORE_REPORT_CONFIG_LINE$1694089578136256' AND MD5NAME='c4d4e7aa0990737c06ce80a684d61bff' AND FILEEXT='cpt' AND SCOPE='finereport' AND EXT='tjrwrkyzypltj' AND PERMANENT='1' AND DOWNLOADABLE='1' AND BIZCATEGORY='master' AND VERSION='1' AND NAME='统计-任务入库因子样品数量_2603.cpt' AND ("SIZE"=16713 OR "SIZE"=${OWNED_REPORT_ASSET_BYTES});
  IF n<>1 OR matched<>1 THEN RAISE_APPLICATION_ERROR(-20232,'Conflicting report attachment'); END IF;
 ELSE
  INSERT INTO T_CORE_FILE (ID,TARGETID,MD5NAME,FILEEXT,SCOPE,EXT,PERMANENT,DOWNLOADABLE,BIZCATEGORY,VERSION,NAME,"SIZE",TIMES,CREATEDTIME) VALUES ('1870065166382528','T_CORE_REPORT_CONFIG_LINE$1694089578136256','c4d4e7aa0990737c06ce80a684d61bff','cpt','finereport','tjrwrkyzypltj','1','1','master','1','统计-任务入库因子样品数量_2603.cpt',${OWNED_REPORT_ASSET_BYTES},0,SYSDATE);
 END IF;
 UPDATE T_CORE_FILE SET "SIZE"=${OWNED_REPORT_ASSET_BYTES} WHERE ID=1870065166382528;
 SELECT COUNT(*) INTO n FROM T_CORE_FILE WHERE ID='1870065166382528' AND TARGETID='T_CORE_REPORT_CONFIG_LINE$1694089578136256' AND MD5NAME='c4d4e7aa0990737c06ce80a684d61bff' AND FILEEXT='cpt' AND SCOPE='finereport' AND EXT='tjrwrkyzypltj' AND PERMANENT='1' AND DOWNLOADABLE='1' AND BIZCATEGORY='master' AND VERSION='1' AND NAME='统计-任务入库因子样品数量_2603.cpt' AND "SIZE"=${OWNED_REPORT_ASSET_BYTES};
 IF n<>1 THEN RAISE_APPLICATION_ERROR(-20233,'Report attachment verification failed'); END IF;
END;
/
COMMIT;
